import React, { useState, useRef, useEffect } from 'react';
import './Product.css';
import Img1 from '../assets/images/img1.jpeg';
import Img2 from '../assets/images/img2.jpeg';
import Img3 from '../assets/images/img3.jpeg';
import Img4 from '../assets/images/img4.jpeg';
import Img5 from '../assets/images/img5.jpeg';
import Img6 from '../assets/images/img6.jpeg';

const products = [
  {
    id: 1,
    name: "Smart Thermostat",
    image: Img1,
    description: "Control your home temperature remotely with smart scheduling and AI.",
  },
  {
    id: 2,
    name: "Smart Switch",
    image: Img2,
    description: "Turn devices on/off from anywhere, with automation support.",
  },
  {
    id: 1,
    name: "Smart Thermostat",
    image: Img3,
    description: "Control your home temperature remotely with smart scheduling and AI.",
  },
  {
    id: 2,
    name: "Smart Switch",
    image: Img4,
    description: "Turn devices on/off from anywhere, with automation support.",
  },
  {
    id: 1,
    name: "Smart Thermostat",
    image: Img5,
    description: "Control your home temperature remotely with smart scheduling and AI.",
  },
  {
    id: 2,
    name: "Smart Switch",
    image: Img6,
    description: "Turn devices on/off from anywhere, with automation support.",
  },
  // add all your products here
];

const Products = () => {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  const openModal = (product) => setSelectedProduct(product);
  const closeModal = () => setSelectedProduct(null);

  return (
    <section
  ref={sectionRef}
  className={`products-section fade-in-section ${isVisible ? 'visible' : ''}`}>
  <div className="container">
    <h2 className="products-title">Our Products</h2>
    <div className="products-grid">
      {products.map((product) => (
        <div className="product-card" key={product.id}>
          <img src={product.image} alt={product.name} />
          <h3>{product.name}</h3>
        </div>
      ))}
    </div>
  </div>
      {selectedProduct && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close" onClick={closeModal}>×</button>
            <img src={selectedProduct.image} alt={selectedProduct.name} />
            <h3>{selectedProduct.name}</h3>
            <p>{selectedProduct.description}</p>
          </div>
        </div>
      )}
    </section>
  );
};

export default Products;
